#include "RelayLink.h"
#include "Crypto.h"
#include <QUuid>
#include <QTimer>
#include <QNetworkDatagram>
static const QByteArray MARK("AMR1",4); static constexpr int CHUNK=1024,MAX_PACKET=65507,MAX_FRAG=64;
RelayLink::RelayLink(const QHostAddress&r,quint16 rp,const QJsonObject&s,Role role,quint16 lp,quint16 gp,QObject*p):QObject(p),m_relay(r),m_relayPort(rp),m_gamePort(gp),m_role(role){
 m_sessionId=s["id"].toString();QUuid u(m_sessionId);m_sid=QByteArray(reinterpret_cast<const char*>(u.toRfc4122().constData()),16);m_key=QByteArray::fromHex(s["key"].toString().toLatin1());m_token=QByteArray::fromHex(s["token"].toString().toLatin1());
 m_local.bind(QHostAddress(QHostAddress::LocalHost), lp);m_remote.bind(QHostAddress(QHostAddress::AnyIPv4), quint16(0));m_clock.start();
}
bool RelayLink::start(QString*e){if(m_local.state()!=QAbstractSocket::BoundState||m_remote.state()!=QAbstractSocket::BoundState||m_relay.isNull()||!m_relayPort){if(e)*e="cannot bind UDP sockets or invalid relay address";return false;}if(m_sid.size()!=16||m_key.size()!=32||m_token.isEmpty()){if(e)*e="invalid session";return false;}connect(&m_local,&QUdpSocket::readyRead,this,&RelayLink::onLocal);connect(&m_remote,&QUdpSocket::readyRead,this,&RelayLink::onRemote);m_timer=new QTimer(this);m_timer->setInterval(1000);connect(m_timer,&QTimer::timeout,this,&RelayLink::heartbeat);m_timer->start();heartbeat();return true;}
quint16 RelayLink::localPort()const{return m_local.localPort();}
void RelayLink::heartbeat(){sendFrame(nullptr);if(!m_peerReady){const QByteArray ping(1,char(0xa0));sendFrame(&ping);}} 
void RelayLink::onLocal(){while(m_local.hasPendingDatagrams()){QNetworkDatagram d=m_local.receiveDatagram();if(d.senderAddress()!=QHostAddress::LocalHost||(m_role==Host&&d.senderPort()!=m_gamePort))continue;if(m_role==Client){m_peerAddr=d.senderAddress();m_peerPort=d.senderPort();}if(!d.data().isEmpty()&&d.data().size()<=MAX_PACKET)sendClear(d.data());}}
void RelayLink::sendClear(const QByteArray&p){int count=(p.size()+CHUNK-1)/CHUNK;if(count<1||count>MAX_FRAG)return;QByteArray group=ArenaCrypto::randomBytes(4);for(int i=0;i<count;i++){QByteArray c=p.mid(i*CHUNK,CHUNK),clear;clear.reserve(7+c.size());clear.append(char(0xa2));clear+=group;clear.append(char(i));clear.append(char(count));clear+=c;sendFrame(&clear);}}
void RelayLink::sendFrame(const QByteArray*clear){QByteArray prefix=MARK+QByteArray(1,m_role==Host?'H':'C')+m_sid,opaque;if(clear){QByteArray nonce=ArenaCrypto::randomBytes(12),ct;if(!ArenaCrypto::aes256GcmEncrypt(m_key,nonce,m_sid,*clear,ct))return;opaque=nonce+ct;}QByteArray tag=ArenaCrypto::hmacSha256(m_token,prefix+opaque).left(16);m_remote.writeDatagram(prefix+tag+opaque,m_relay,m_relayPort);}
void RelayLink::onRemote(){while(m_remote.hasPendingDatagrams()){QNetworkDatagram d=m_remote.receiveDatagram();QByteArray b=d.data();if(d.senderAddress()!=m_relay||d.senderPort()!=m_relayPort||b.size()<50||b.left(5)!=(MARK+"D")||b.mid(5,16)!=m_sid)continue;QByteArray blob=b.mid(21),nonce=blob.left(12);if(blob.size()<29||m_seen.contains(nonce))continue;QByteArray clear;if(!ArenaCrypto::aes256GcmDecrypt(m_key,nonce,m_sid,blob.mid(12),clear))continue;m_seen.insert(nonce);m_seenQ.enqueue(nonce);if(m_seenQ.size()>4096)m_seen.remove(m_seenQ.dequeue());if(clear.size()==1&&quint8(clear[0])==0xa0){const QByteArray pong(1,char(0xa1));sendFrame(&pong);continue;}if(clear.size()==1&&quint8(clear[0])==0xa1){m_peerReady=true;m_timer->setInterval(5000);continue;}if(clear.size()<7||quint8(clear[0])!=0xa2)continue;QByteArray gid=clear.mid(1,4);int index=quint8(clear[5]),count=quint8(clear[6]);if(count<1||count>MAX_FRAG||index>=count)continue;qint64 now=m_clock.elapsed();if(m_pending.size()>64){for(auto it=m_pending.begin();it!=m_pending.end();)if(now-it->created>3000)it=m_pending.erase(it);else++it;if(m_pending.size()>64)m_pending.clear();}auto &p=m_pending[gid];if(p.count!=count||now-p.created>3000){p=Pending{now,count,{}};}p.parts[index]=clear.mid(7);if(p.parts.size()!=count)continue;QByteArray all;for(int i=0;i<count;i++){if(!p.parts.contains(i)){all.clear();break;}all+=p.parts[i];}m_pending.remove(gid);if(all.isEmpty()||all.size()>MAX_PACKET)continue;if(m_role==Host)m_local.writeDatagram(all,QHostAddress::LocalHost,m_gamePort);else if(m_peerPort)m_local.writeDatagram(all,m_peerAddr,m_peerPort);}}
